"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** The one activity the island reports. Each `kind` gives the pill its own shape. */
export type StatusIslandState =
  | { kind: "idle"; label?: string }
  /** `seconds` is the elapsed time. The parent advances it, so the island stays a plain view. */
  | { kind: "timer"; label: string; seconds: number }
  /** `progress` runs from 0 to 1. */
  | { kind: "upload"; fileName: string; progress: number }
  | { kind: "call"; caller: string };

/** Props for a status island. It holds no state of its own: pass the activity in `state`. */
export type StatusIslandProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  state: StatusIslandState;
  onAccept?: () => void;
  onDecline?: () => void;
};

// Critically damped: the pill reaches its new shape fast and does not wobble.
const RESIZE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const ENTER: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const EXIT: Transition = { duration: 0.12, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

const PATHS = {
  clock: "M10 3a7 7 0 1 1 0 14 7 7 0 0 1 0-14zM9 6v5l4 2 .8-1.6-2.8-1.5V6z",
  upload: "M10 3l6 6-1.4 1.4L11 6.8V17H9V6.8l-3.6 3.6L4 9z",
  phone: "M6 2h3l1 4-2 1.5a9 9 0 0 0 4.5 4.5L14 10l4 1v3a2 2 0 0 1-2 2C9.4 16 4 10.6 4 4a2 2 0 0 1 2-2z",
  // Both strokes at full opacity: a faded half reads as a rendering fault.
  close: "M5.4 4 10 8.6 14.6 4 16 5.4 11.4 10l4.6 4.6-1.4 1.4-4.6-4.6L5.4 16 4 14.6 8.6 10 4 5.4z",
};

const glyph = (name: keyof typeof PATHS) => (
  <svg aria-hidden="true" viewBox="0 0 20 20" fill="currentColor" fillRule="evenodd" className="size-4 shrink-0">
    <path d={PATHS[name]} />
  </svg>
);

const clockText = (total: number) => {
  const seconds = Math.max(0, Math.floor(total));
  const pad = (value: number) => String(value).padStart(2, "0");
  const minutes = Math.floor(seconds / 60);
  return minutes >= 60
    ? `${Math.floor(minutes / 60)}:${pad(minutes % 60)}:${pad(seconds % 60)}`
    : `${pad(minutes)}:${pad(seconds % 60)}`;
};

const CALL_BUTTON =
  "relative flex size-8 cursor-pointer touch-manipulation items-center justify-center rounded-full outline-none before:absolute before:-inset-1.5 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-foreground";

function content(state: StatusIslandState, onAccept?: () => void, onDecline?: () => void): ReactNode {
  if (state.kind === "timer") {
    return (
      <div className="flex h-10 items-center gap-2 px-4 text-sm">
        {glyph("clock")}
        <span className="max-w-40 truncate">{state.label}</span>
        {/* A timer is not announced every second; a screen reader reads it on demand. */}
        <span role="timer" aria-live="off" className="font-medium tabular-nums">
          {clockText(state.seconds)}
        </span>
      </div>
    );
  }
  if (state.kind === "upload") {
    const progress = Math.min(Math.max(state.progress, 0), 1);
    const percent = Math.round(progress * 100);
    return (
      <div className="flex h-10 items-center gap-2 px-4 text-sm">
        {glyph("upload")}
        <span className="max-w-32 truncate">{state.fileName}</span>
        <span
          role="progressbar"
          aria-label={`Uploading ${state.fileName}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent}
          className="h-1 w-16 overflow-hidden rounded-full bg-background/25"
        >
          {/* Linear, because the bar stands for work done, and scaleX keeps it off the layout. */}
          <motion.span
            className="block h-full origin-left rounded-full bg-background"
            initial={false}
            animate={{ scaleX: progress }}
            transition={{ duration: 0.2, ease: "linear" }}
          />
        </span>
        <span aria-hidden="true" className="w-10 text-right font-medium tabular-nums">
          {percent}%
        </span>
      </div>
    );
  }
  if (state.kind === "call") {
    return (
      <div className="flex h-14 items-center gap-3 pr-3 pl-5">
        <p className="flex flex-col pr-2 leading-tight">
          <span className="max-w-36 truncate text-sm font-medium">{state.caller}</span>
          <span className="text-xs opacity-70">Incoming call</span>
        </p>
        <button
          type="button"
          aria-label={`Decline the call from ${state.caller}`}
          onClick={onDecline}
          className={cn(CALL_BUTTON, "bg-background/20")}
        >
          {glyph("close")}
        </button>
        <button
          type="button"
          aria-label={`Accept the call from ${state.caller}`}
          onClick={onAccept}
          className={cn(CALL_BUTTON, "bg-background text-foreground")}
        >
          {glyph("phone")}
        </button>
      </div>
    );
  }
  return (
    <div className="flex h-8 items-center gap-2 px-3 text-xs">
      <span aria-hidden="true" className="size-2 rounded-full bg-background/60" />
      {state.label ?? "No activity"}
    </div>
  );
}

/**
 * A pill that reports one live activity and changes shape with it. The pill
 * resizes on a spring while the old content fades out and the new fades in.
 */
export function StatusIsland({ state, onAccept, onDecline, className, ...rootProps }: StatusIslandProps) {
  const reduceMotion = useReducedMotion();
  const measured = useRef<HTMLDivElement>(null);
  // Null until the content has been measured; the pill then sizes itself like any inline box.
  const [size, setSize] = useState<{ width: number; height: number } | null>(null);

  useEffect(() => {
    const node = measured.current;
    if (!node || !("ResizeObserver" in window)) return;
    const observer = new ResizeObserver(() => {
      const { offsetWidth: width, offsetHeight: height } = node;
      if (width > 0 && height > 0) {
        setSize((previous) => (previous?.width === width && previous.height === height ? previous : { width, height }));
      }
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, filter: "blur(4px)" };

  return (
    <div role="status" {...rootProps} className={cn("inline-flex", className)}>
      {/* Width and height are layout properties, but this is one small element that changes a few times a minute. */}
      <motion.div
        initial={false}
        animate={size ?? undefined}
        transition={reduceMotion ? INSTANT : RESIZE}
        className="relative overflow-hidden rounded-full bg-foreground text-background shadow-md"
      >
        <div ref={measured} className="w-max">
          {/* popLayout lifts the leaving content out of the flow, so the box already has its next size. */}
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.div
              key={state.kind}
              initial={hidden}
              animate={{ opacity: 1, scale: 1, filter: "blur(0px)", transition: ENTER }}
              exit={{ ...hidden, transition: EXIT }}
            >
              {content(state, onAccept, onDecline)}
            </motion.div>
          </AnimatePresence>
        </div>
      </motion.div>
    </div>
  );
}
